package main

import (
	"encoding/csv"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

type entry struct {
	Date     time.Time
	Account  string
	Category string
	Cents    int64
	Note     string
}

type options struct {
	File     string
	Month    string
	Account  string
	Category string
	Limit    int
}

func main() {
	if err := run(os.Args[1:], os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func parseOptions(args []string) (options, error) {
	var opts options
	flags := flag.NewFlagSet("ledger", flag.ContinueOnError)
	flags.StringVar(&opts.File, "file", "ledger.csv", "Path to the account book")
	flags.StringVar(&opts.Month, "month", "", "Month in YYYY-MM form")
	flags.StringVar(&opts.Account, "account", "", "Account name")
	flags.StringVar(&opts.Category, "category", "", "Category name")
	flags.IntVar(&opts.Limit, "limit", 20, "Maximum number of entries")
	if err := flags.Parse(args); err != nil {
		return opts, err
	}
	if opts.Limit < 1 {
		return opts, errors.New("limit must be positive")
	}
	if opts.Month != "" {
		if _, err := time.Parse("2006-01", opts.Month); err != nil {
			return opts, errors.New("month must use YYYY-MM")
		}
	}
	return opts, nil
}

func run(args []string, output io.Writer) error {
	opts, err := parseOptions(args)
	if err != nil {
		return err
	}
	file, err := os.Open(opts.File)
	if err != nil {
		return err
	}
	defer file.Close()
	entries, err := readEntries(file)
	if err != nil {
		return err
	}
	entries = filterEntries(entries, opts)
	sort.SliceStable(entries, func(i, j int) bool {
		return entries[i].Date.Before(entries[j].Date)
	})
	if len(entries) > opts.Limit {
		entries = entries[:opts.Limit]
	}
	return writeEntries(output, entries)
}

func readEntries(input io.Reader) ([]entry, error) {
	reader := csv.NewReader(input)
	reader.FieldsPerRecord = 5
	header, err := reader.Read()
	if err != nil {
		return nil, err
	}
	if strings.Join(header, ",") != "date,account,category,amount,note" {
		return nil, errors.New("unexpected account book columns")
	}
	var entries []entry
	for row := 2; ; row++ {
		record, err := reader.Read()
		if err == io.EOF {
			return entries, nil
		}
		if err != nil {
			return nil, fmt.Errorf("row %d: %w", row, err)
		}
		item, err := parseEntry(record)
		if err != nil {
			return nil, fmt.Errorf("row %d: %w", row, err)
		}
		entries = append(entries, item)
	}
}

func parseEntry(record []string) (entry, error) {
	var item entry
	date, err := time.Parse("2006-01-02", record[0])
	if err != nil {
		return item, errors.New("date must use YYYY-MM-DD")
	}
	cents, err := parseAmount(record[3])
	if err != nil {
		return item, err
	}
	item.Date = date
	item.Account = record[1]
	item.Category = record[2]
	item.Cents = cents
	item.Note = record[4]
	if item.Account == "" {
		return item, errors.New("account is required")
	}
	return item, nil
}

func parseAmount(text string) (int64, error) {
	negative := strings.HasPrefix(text, "-")
	if negative {
		text = strings.TrimPrefix(text, "-")
	}
	parts := strings.Split(text, ".")
	if len(parts) > 2 || parts[0] == "" {
		return 0, errors.New("invalid amount")
	}
	whole, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil || whole < 0 || whole > 9000000000 {
		return 0, errors.New("amount is outside the supported range")
	}
	fraction := "00"
	if len(parts) == 2 {
		fraction = parts[1]
		if len(fraction) == 1 {
			fraction += "0"
		}
		if len(fraction) != 2 {
			return 0, errors.New("amount needs at most two decimal places")
		}
	}
	cents, err := strconv.ParseInt(fraction, 10, 64)
	if err != nil || cents < 0 || cents > 99 {
		return 0, errors.New("invalid decimal amount")
	}
	cents += whole * 100
	if negative {
		cents = -cents
	}
	return cents, nil
}

func filterEntries(entries []entry, opts options) []entry {
	result := make([]entry, 0, len(entries))
	for _, item := range entries {
		if opts.Month != "" && item.Date.Format("2006-01") != opts.Month {
			continue
		}
		if opts.Account != "" && item.Account != opts.Account {
			continue
		}
		if opts.Category != "" && item.Category != opts.Category {
			continue
		}
		result = append(result, item)
	}
	return result
}

func writeEntries(output io.Writer, entries []entry) error {
	writer := csv.NewWriter(output)
	if err := writer.Write([]string{"date", "account", "category", "amount", "note"}); err != nil {
		return err
	}
	for _, item := range entries {
		record := []string{
			item.Date.Format("2006-01-02"),
			item.Account,
			item.Category,
			formatAmount(item.Cents),
			item.Note,
		}
		if err := writer.Write(record); err != nil {
			return err
		}
	}
	writer.Flush()
	return writer.Error()
}

func formatAmount(cents int64) string {
	sign := ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return fmt.Sprintf("%s%d.%02d", sign, cents/100, cents%100)
}

