package ledger

import (
	"fmt"
	"sort"
	"time"
)

type Entry struct {
	Date     time.Time
	Account  string
	Category string
	Cents    int64
}

type Total struct {
	Name  string
	Cents int64
	Count int
}

func ByCategory(entries []Entry) []Total {
	groups := make(map[string]Total)
	for _, item := range entries {
		name := item.Category
		total := groups[name]
		total.Name = name
		total.Cents += item.Cents
		total.Count++
		groups[name] = total
	}
	result := make([]Total, 0, len(groups))
	for _, total := range groups {
		result = append(result, total)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Name < result[j].Name
	})
	return result
}

func MonthLabel(date time.Time) string {
	return date.Format("January 2006")
}

func TotalLabel(total Total) string {
	return fmt.Sprintf("%s: %d entries", total.Name, total.Count)
}

