import (
	"encoding/csv"
	"fmt"
	"io"
	"strings"
)

func ReadAccounts(input io.Reader) (map[string]string, error) {
	reader := csv.NewReader(input)
	reader.FieldsPerRecord = 2
	accounts := make(map[string]string)
	for row := 1; ; row++ {
		record, err := reader.Read()
		if err == io.EOF {
			return accounts, nil
		}
		if err != nil {
			return nil, fmt.Errorf("account row %d: %w", row, err)
		}
		name := record[0]
		currency := record[1]
		if name == "" || currency == "" {
			return nil, fmt.Errorf("account row %d is incomplete", row)
		}
		accounts[name] = currency
	}
}

func AccountNames(accounts map[string]string) string {
	var names []string
	for name := range accounts {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}

