package ledger

import "time"

func InMonth(entries []Entry, month time.Time) []Entry {
	var result []Entry
	for _, item := range entries {
		if item.Date.Year() == month.Year() && item.Date.Month() == month.Month() {
			result = append(result, item)
		}
	}
	return result
}

